// A card's comment threads as agents see and work them (docs/specs/026-plan/plan-agents.md "Comment threads"): the
// MCP's list_threads and change_threads and the CLI's `thread` verbs share this. A thread is named by its id, an id
// prefix of four characters or more, or its title (case aside); a comment by its id or an id prefix; a card as
// list_items names it ("#12"). Every comment an agent writes is marked Generated by AI by the api, which also
// refuses an agent's edit or delete of any comment it did not write.

import type { ApiClient } from '@liveworkspace/api-client';
import type {
  CardThreadWriteResponse,
  CardThreadsResponse,
  ItemsResponse,
  PlanResponse,
} from '@liveplanner/api-schema';
import {
  COMMENTS_FIELD,
  commentsFieldsOf,
  customFieldOf,
  itemTitle,
  resolveItem,
  statusKey,
  threadFieldOn,
  typeIn,
  type Item,
  type ItemTypeDef,
} from '@liveplanner/items';
import type { CardRef, CardThread, Comment } from '@liveplanner/project';
import { apiRefusalOf } from './api-refusal';
import { planPath } from './plan-state';
import { itemsPath } from '../verbs/shared';

export const threadsPath = (projectId: string) =>
  `/projects/${encodeURIComponent(projectId)}/threads`;

export const THREAD_STATUSES = ['open', 'resolved', 'all'] as const;
export type ThreadStatus = (typeof THREAD_STATUSES)[number];

// A thread or a comment named by a prefix needs at least this much of its id.
export const THREAD_PREFIX_MIN = 4;

export type ThreadChange =
  // `field`: the Comments field it starts in, by name or id (the built-in Comments when absent).
  | { op: 'start'; item: string; text: string; field?: string }
  | { op: 'reply'; thread: string; text: string }
  | { op: 'resolve'; thread: string }
  | { op: 'reopen'; thread: string }
  | { op: 'edit'; thread: string; comment: string; text: string }
  | { op: 'delete'; thread: string; comment: string };

// One comment as an agent reads it.
export type ListedComment = {
  id: string;
  author: string;
  at: string;
  text: string;
  ai?: true;
  edited?: true;
};

// One thread as an agent reads it.
export type ListedThread = {
  id: string;
  title: string;
  state: 'open' | 'resolved';
  resolvedBy?: string;
  cards: string[];
  // The Comments field it shows under on its first card here, by name.
  field?: string;
  comments: ListedComment[];
};

const iso = (ms: number) => new Date(ms).toISOString();

// A card a thread is on, as people say it: "#12 Title" here, "#4 in Sprint 12" in another plan.
function cardName(card: CardRef, projectId: string, items: ReadonlyMap<string, Item>): string {
  const num = card.key !== null ? `#${card.key}` : 'a card';
  if (card.projectId !== projectId) return `${num} in ${card.projectName || 'another plan'}`;
  const item = items.get(card.itemId);
  return item ? `${num} ${itemTitle(item) || 'Untitled'}` : num;
}

export function listedComment(c: Comment): ListedComment {
  return {
    id: c.id,
    author: c.authorName,
    at: iso(c.createdAt),
    text: c.text,
    ...(c.ai ? { ai: true as const } : {}),
    ...(c.editedAt ? { edited: true as const } : {}),
  };
}

// A Comments field's name (one `commentsFieldsOf(type)` names): the built-in's "Comments", else the field's label.
const commentsFieldName = (type: ItemTypeDef, field: string): string =>
  field === COMMENTS_FIELD ? 'Comments' : customFieldOf(type, field)!.label;

// The Comments field a thread shows under (docs/specs/026-plan/item-types.md "Comments and Votes fields"), by name, on
// its first card in this plan: the plan's types say which; none when no card here has a type with a Comments field.
function threadFieldName(
  t: CardThread,
  projectId: string,
  items: ReadonlyMap<string, Item>,
  types: readonly ItemTypeDef[],
): string | undefined {
  const first = t.cards.find((c) => c.projectId === projectId && items.has(c.itemId));
  if (!first) return undefined;
  const type = typeIn(types, items.get(first.itemId)!.type);
  const field = threadFieldOn(t, type);
  return field === null ? undefined : commentsFieldName(type, field);
}

export function listedThread(
  t: CardThread,
  projectId: string,
  items: ReadonlyMap<string, Item>,
  types: readonly ItemTypeDef[] = [],
): ListedThread {
  const field = threadFieldName(t, projectId, items, types);
  return {
    id: t.id,
    title: t.title,
    state: t.resolved ? 'resolved' : 'open',
    ...(t.resolved && t.resolvedBy ? { resolvedBy: t.resolvedBy } : {}),
    cards: t.cards.map((c) => cardName(c, projectId, items)),
    ...(field ? { field } : {}),
    comments: t.comments.map(listedComment),
  };
}

export type ThreadsState = { threads: CardThread[]; items: Item[]; types: readonly ItemTypeDef[] };

/** The plan's threads, its items and its card types (for each thread's Comments field), read together. */
export async function readThreadsState(api: ApiClient, projectId: string): Promise<ThreadsState> {
  const [{ threads }, { items }, { types }] = await Promise.all([
    api.json<CardThreadsResponse>(threadsPath(projectId)),
    api.json<ItemsResponse>(itemsPath(projectId)),
    api.json<PlanResponse>(planPath(projectId)),
  ]);
  return { threads, items, types };
}

/** The Comments field of a card of `type` that `ref` names: by id, or by name (case and spacing aside), the built-in
 *  as "Comments". Unknown, refused naming the ones there are. */
export function resolveCommentsField(ref: string, type: ItemTypeDef): Found<string> {
  const fields = commentsFieldsOf(type);
  const key = statusKey(ref);
  const found = fields.find(
    (f) => f === ref.trim() || statusKey(commentsFieldName(type, f)) === key,
  );
  if (found) return { ok: true, value: found };
  return {
    ok: false,
    code: 'field_unknown',
    message: fields.length
      ? `${type.label} cards have no Comments field "${ref}". Their Comments fields: ${fields
          .map((f) => commentsFieldName(type, f))
          .join(', ')}.`
      : `${type.label} cards have no Comments field: add one with change_card_types.`,
  };
}

type Found<T> = { ok: true; value: T } | { ok: false; code: string; message: string };

/** The thread `ref` names: an id, a prefix of at least THREAD_PREFIX_MIN, or a title (case aside). */
export function resolveThread(ref: string, threads: readonly CardThread[]): Found<CardThread> {
  const want = ref.trim();
  const exact = threads.find((t) => t.id === want);
  if (exact) return { ok: true, value: exact };
  const lower = want.toLowerCase();
  const titled = threads.filter((t) => t.title.toLowerCase() === lower);
  const prefixed =
    want.length >= THREAD_PREFIX_MIN ? threads.filter((t) => t.id.startsWith(want)) : [];
  const matches = titled.length ? titled : prefixed;
  if (matches.length === 1) return { ok: true, value: matches[0]! };
  const listed = (matches.length ? matches : threads)
    .slice(0, 10)
    .map((t) => `${t.id} "${t.title}"`)
    .join('; ');
  return {
    ok: false,
    code: matches.length ? 'thread_ambiguous' : 'thread_unknown',
    message: matches.length
      ? `"${ref}" names more than one thread: ${listed}`
      : threads.length
        ? `No thread "${ref}". The threads: ${listed}`
        : `No thread "${ref}": this plan has no threads. Start one with start.`,
  };
}

/** The comment `ref` names in a thread: an id, or a prefix of at least THREAD_PREFIX_MIN. */
export function resolveComment(ref: string, thread: CardThread): Found<Comment> {
  const want = ref.trim();
  const exact = thread.comments.find((c) => c.id === want);
  if (exact) return { ok: true, value: exact };
  const matches =
    want.length >= THREAD_PREFIX_MIN ? thread.comments.filter((c) => c.id.startsWith(want)) : [];
  if (matches.length === 1) return { ok: true, value: matches[0]! };
  return {
    ok: false,
    code: matches.length ? 'comment_ambiguous' : 'comment_unknown',
    message: `${matches.length ? `"${ref}" names more than one comment` : `No comment "${ref}"`} in "${thread.title}": ${thread.comments
      .map((c) => `${c.id} by ${c.authorName}`)
      .join('; ')}`,
  };
}

/** The threads a listing answers: open, resolved or all, on one card when `item` names it. */
export function threadListing(
  state: ThreadsState,
  projectId: string,
  status: ThreadStatus,
  item?: string,
): { ok: true; threads: ListedThread[] } | { ok: false; message: string } {
  let threads = state.threads;
  if (item !== undefined) {
    const found = resolveItem(item, state.items);
    if (!found.ok) return { ok: false, message: found.message };
    threads = threads.filter((t) =>
      t.cards.some((c) => c.projectId === projectId && c.itemId === found.item.id),
    );
  }
  if (status !== 'all') threads = threads.filter((t) => t.resolved === (status === 'resolved'));
  const items = new Map(state.items.map((i) => [i.id, i]));
  const sorted = [...threads].sort((a, b) => b.updatedAt - a.updatedAt);
  return {
    ok: true,
    threads: sorted.map((t) => listedThread(t, projectId, items, state.types)),
  };
}

// Words for a refusal the api gives a thread write (docs/specs/026-plan/plan-agents.md "Errors that teach").
const THREAD_REFUSALS: Readonly<Record<string, string>> = {
  forbidden:
    'that comment was written by a person (or by someone else): an agent edits and deletes only its own comments.',
  thread_not_found: 'that thread is gone. list_threads lists the threads.',
  comment_not_found: 'that comment is gone. list_threads lists the comments.',
  comments_full: 'that thread holds the most comments it can (200): start a new thread.',
  threads_full: 'that card holds the most threads it can (50).',
  title_too_long: 'a thread title holds up to 120 characters.',
  field_invalid: 'that card’s type has no such Comments field. list_items lists its card types.',
};

type Stop = { code: string; message: string };

const stop = (code: string, message: string): never => {
  throw Object.assign(new Error(message), { stopCode: code });
};

function refusedBy(err: unknown): Stop | null {
  const known = (err as { code?: string }).code;
  const words = known ? THREAD_REFUSALS[known] : undefined;
  if (words) return { code: known!, message: `The api refused it: ${words}` };
  return apiRefusalOf(err);
}

// The comment an agent may edit or delete: one an agent wrote (the api refuses any other too, and says the same).
function ownComment(ref: string, thread: CardThread): Comment {
  const found = resolveComment(ref, thread);
  if (!found.ok) return stop(found.code, found.message);
  if (!found.value.ai)
    return stop(
      'forbidden',
      `Comment ${found.value.id} by ${found.value.authorName} was written by a person: an agent edits and deletes only its own comments (those marked ai).`,
    );
  return found.value;
}

const threadPath = (projectId: string, id: string) =>
  `${threadsPath(projectId)}/${encodeURIComponent(id)}`;

/** Applies `changes` in order, each against the threads as the ones before it left them. A refusal stops the rest
 *  and says what was applied before it. */
export async function applyThreadChanges(
  api: ApiClient,
  projectId: string,
  changes: readonly ThreadChange[],
  initial: ThreadsState,
): Promise<{ applied: string[]; refusal?: Stop }> {
  const applied: string[] = [];
  let threads = [...initial.threads];
  const keep = (t: CardThread | null, id: string) => {
    threads = t ? [...threads.filter((x) => x.id !== t.id), t] : threads.filter((x) => x.id !== id);
  };
  const thread = (ref: string) => {
    const found = resolveThread(ref, threads);
    return found.ok ? found.value : stop(found.code, found.message);
  };
  for (const change of changes) {
    try {
      const post = (path: string, body?: unknown, method = 'POST') =>
        api.json<CardThreadWriteResponse>(path, {
          method,
          ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
        });
      switch (change.op) {
        case 'start': {
          const found = resolveItem(change.item, initial.items);
          if (!found.ok) stop(found.code, found.message);
          const item = (found as { item: Item }).item;
          let field: string | undefined;
          if (change.field !== undefined) {
            const named = resolveCommentsField(change.field, typeIn(initial.types, item.type));
            if (!named.ok) stop(named.code, named.message);
            field = (named as { value: string }).value;
          }
          const { thread: made } = await post(
            `${itemsPath(projectId)}/${encodeURIComponent(item.id)}/threads`,
            { text: change.text, ...(field && field !== COMMENTS_FIELD ? { field } : {}) },
          );
          keep(made, '');
          applied.push(`+ thread ${made!.id} "${made!.title}" on #${item.key}`);
          break;
        }
        case 'reply': {
          const t = thread(change.thread);
          const out = await post(`${threadPath(projectId, t.id)}/comments`, { text: change.text });
          keep(out.thread, t.id);
          applied.push(`+ comment ${out.commentId ?? ''} on "${t.title}"`.replace('  ', ' '));
          break;
        }
        case 'resolve':
        case 'reopen': {
          const t = thread(change.thread);
          // Already so answers 204, nothing: the thread as it was.
          const { body } = await api.text(`${threadPath(projectId, t.id)}/${change.op}`, {
            method: 'POST',
          });
          if (body) keep((JSON.parse(body) as CardThreadWriteResponse).thread, t.id);
          applied.push(`~ thread "${t.title}" ${change.op === 'resolve' ? 'resolved' : 'open'}`);
          break;
        }
        case 'edit': {
          const t = thread(change.thread);
          const id = ownComment(change.comment, t).id;
          const out = await post(
            `${threadPath(projectId, t.id)}/comments/${encodeURIComponent(id)}`,
            { text: change.text },
            'PUT',
          );
          keep(out.thread, t.id);
          applied.push(`~ comment ${id} on "${t.title}"`);
          break;
        }
        case 'delete': {
          const t = thread(change.thread);
          const id = ownComment(change.comment, t).id;
          const out = await post(
            `${threadPath(projectId, t.id)}/comments/${encodeURIComponent(id)}`,
            undefined,
            'DELETE',
          );
          keep(out.thread, t.id);
          applied.push(
            `- comment ${id} from "${t.title}"${out.thread ? '' : ' (its last: the thread went)'}`,
          );
          break;
        }
      }
    } catch (err) {
      const code = (err as { stopCode?: string }).stopCode;
      if (code) return { applied, refusal: { code, message: (err as Error).message } };
      const refusal = refusedBy(err);
      if (!refusal) throw err;
      return { applied, refusal };
    }
  }
  return { applied };
}
